import { z } from "zod";
import { pooledAttribution, SAY_FOLLOWED } from "../domain";
import { wakeUp } from "../night/timeline";

const count = z.number().int().nonnegative();

/** Counts until enough nights are pooled; a percentage only after that. */
export const attributionView = z.discriminatedUnion("display", [
  z.object({
    display: z.literal("counts"),
    nightsPooled: count,
    wakeUps: count,
    followedSpike: count,
    /** "3 of 4 wake-ups followed a spike" */
    text: z.string().min(1),
  }),
  z.object({
    display: z.literal("percentage"),
    nightsPooled: count,
    wakeUps: count,
    followedSpike: count,
    /** 100 * followedSpike / wakeUps. */
    percent: z.number(),
    /** "50% of wake-ups followed a spike" */
    text: z.string().min(1),
  }),
]);

export type AttributionView = z.infer<typeof attributionView>;

export const attributionForNightInput = z.object({
  nightId: z.uuid(),
});

export type AttributionForNightInput = z.infer<typeof attributionForNightInput>;

/** What `attribution.forNight` returns. One night is counts; `pooled` may be a percentage. */
export const attributionForNightOutput = z.object({
  nightId: z.uuid(),
  wakeUps: z.array(wakeUp),
  followedSpike: count,
  /** Share of random windows from this night that contained a spike. */
  randomWindowRate: z.number().min(0).max(1),
  /** This night on its own. */
  night: attributionView,
  /** Every night already attributed for this user. */
  pooled: attributionView,
});

export type AttributionForNightOutput = z.infer<typeof attributionForNightOutput>;
});

export const evidenceRecord = z.object({
  /** SHA-256 of the canonical night log, hex */
  hash: z.string().nullable(),
  /** Solana Memo transaction signature */
  memoSignature: z.string().nullable(),
});

/** Everything the night screen draws. */
export const nightTimeline = z.object({
  nightId: z.uuid(),
  /** The evening's London date, from `nightOf` */
  night: z.iso.date(),
  startedAt: isoDateTime,
  endedAt: isoDateTime,
  baselineDb: z.number(),
  /** Downsampled relative dB for drawing: [epoch seconds, dB] */
  noise: z.array(z.tuple([z.number(), z.number()])),
  stages: z.array(z.object({ start: isoDateTime, end: isoDateTime, stage: sleepStage })),
  events: z.array(nightEvent),
  wakeUps: z.array(wakeUp),
  attribution: attributionResult.nullable(),
  evidence: evidenceRecord,
});

/** One per night in MongoDB `nights` and in night lists. */
export const nightSummary = z.object({
  nightId: z.uuid(),
  userId: z.uuid(),
  night: z.iso.date(),
  startedAt: isoDateTime,
  endedAt: isoDateTime,
  eventCount: z.number().int(),
  labelCounts: z.partialRecord(noiseLabel, z.number().int()),
  outsideRecommendedHoursCount: z.number().int(),
  wakeUpCount: z.number().int(),
  attribution: attributionResult.nullable(),
  evidence: evidenceRecord,
});

export type NightEvent = z.infer<typeof nightEvent>;
